let tot=0,gaps=[],waivers=0,failres=[],noRecpt=[],staleM=[],staleS=[];
for(const it of (c.items||[])){
  const vi=it.verificationIntent||{}, ve=it.verificationEvidence||[];
  const by={}; for(const e of ve){(by[e.intentRef]=by[e.intentRef]||[]).push(e);}
  console.log('=== '+it.id+' ['+it.status+'] ev='+ve.length);
  for(const col of ['happy','edge','adversarial']){
    (vi[col]||[]).forEach((intent,i)=>{
      tot++;
      const ref=it.id+':'+col+':'+i;
      const evs=by[ref]||[];
      const good=evs.filter(e=>e.result!=='fail');
      if(evs.some(e=>e.result==='fail')) failres.push(ref);
      if(evs.some(e=>e.kind==='waiver')) waivers++;
      if(good.length===0){gaps.push(ref+' ['+intent.priority+']');}
      else {
        for(const e of good){
          if(!e.receipt) noRecpt.push(ref+'/'+e.kind);
          if(e.materialHash&&e.materialHash!==cur.material) staleM.push(ref);
          if(e.storyFilesHash&&e.storyFilesHash!==cur.storyFiles) staleS.push(ref);
